# Secret Manager secrets each VM service receives (architecture.md §26; K78, K81).
# Format: <service> <ENV_VAR>=<secret-id>. vm/bin/load-secrets.sh writes /run/kalkan/<service>.env
# (tmpfs, 0600) with these lines; the service's compose env_file entry reads it. A secret without
# an enabled version is skipped with a warning, so the feature that needs it stays off.
# The VM service account may read exactly these secrets (infra/terraform/secrets.tf). Only
# cloud-sql-proxy, worker-default, worker-ai and ops reach the metadata server for its token
# (vm/bin/firewall.sh, K82), so no other container can read another service's secrets.
# REDIS_URL carries the password of a Redis user (K82): kalkan for the application containers,
# browser for worker-browser.
worker-default  DATABASE_URL_WORKER=database-url-worker
worker-default  REDIS_URL=redis-url
worker-default  WEBRISK_API_KEY=webrisk-api-key
worker-default  CZDS_USERNAME=czds-username
worker-default  CZDS_PASSWORD=czds-password
worker-default  POSTMARK_SERVER_TOKEN=postmark-server-token
worker-default  SENTRY_DSN=sentry-dsn

scheduler       DATABASE_URL_WORKER=database-url-worker
scheduler       REDIS_URL=redis-url
scheduler       SENTRY_DSN=sentry-dsn

ct-consumer     DATABASE_URL_WORKER=database-url-worker
ct-consumer     REDIS_URL=redis-url
ct-consumer     SENTRY_DSN=sentry-dsn

# No database URL and no cloud credentials (K6).
worker-browser  REDIS_URL=redis-browser-url
worker-browser  PROXY_MAP=proxy-map
worker-browser  SENTRY_DSN=sentry-dsn

worker-ai       DATABASE_URL_WORKER=database-url-worker
worker-ai       REDIS_URL=redis-url
worker-ai       ANTHROPIC_API_KEY=anthropic-api-key
worker-ai       SENTRY_DSN=sentry-dsn

# Also the CLI commands that need the TOTP key (`docker compose exec ops kalkan staff create`).
ops             DATABASE_URL_WORKER=database-url-worker
ops             REDIS_URL=redis-url
ops             TOTP_ENCRYPTION_KEY=totp-encryption-key
ops             SENTRY_DSN=sentry-dsn

migrate         DATABASE_URL_MIGRATE=database-url-migrate

# kalkan_owner's password for psql, and the passwords db-bootstrap.sh sets on the app roles.
psql            PGPASSWORD=db-owner-password
psql            DB_API_PASSWORD=db-api-password
psql            DB_WORKER_PASSWORD=db-worker-password

grafana         GF_SECURITY_ADMIN_PASSWORD=grafana-admin-password

# Not an env file for the container: load-secrets.sh renders the Alertmanager configuration
# (vm/bin/render-alertmanager.sh) and keeps the password only in its password file. The relay,
# user name, sender and recipient are deploy settings in app.env (ALERT_SMTP_*).
alertmanager    ALERT_SMTP_PASSWORD=alert-smtp-password

# Not an env file for the container either: load-secrets.sh renders the Redis ACL file
# /run/kalkan/redis/users.acl from these (SHA-256 hashes only) and fails without them.
redis           REDIS_APP_PASSWORD=redis-app-password
redis           REDIS_BROWSER_PASSWORD=redis-browser-password
